// Accepts ANY TradingView body. Never drops a signal: if it can't be parsed, the raw text is shown.
const KEY = 'change-me';
const ACT = {'1':'BUY CALLS','-1':'BUY PUTS','2':'SELL HALF CALLS','-2':'SELL HALF PUTS','3':'EXIT CALLS','-3':'EXIT PUTS'};
const STR = {'1':'S1 ORB 30m','2':'S2 SWEEP REVERSAL','3':'S3 VWAP','4':'S4 OPENING DRIVE','5':'S5 TREND PULLBACK','6':'S6 TLP PATIENCE'};
const store = $getWorkflowStaticData('global');
store.signals = store.signals || [];
// New trading day (ET) -> clear the dashboard list. Every alert is kept in the Google Sheet log.
const etDay = () => new Date().toLocaleString('en-CA', { timeZone: 'America/New_York' }).slice(0, 10);
const today = etDay();
if (store.day !== today) { store.signals = []; store.day = today; }
store.log = store.log || [];   // permanent alert log (never reset), read by the Google Sheet
for (const item of $input.all()) {
  let b = item.json.body;
  if ((b == null || (typeof b === 'object' && Object.keys(b).length === 0)) && item.binary && item.binary.data) {
    b = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  }
  if (b == null) continue;
  let raw = typeof b === 'string' ? b : JSON.stringify(b);
  if (typeof b === 'string') {
    const cleaned = b.replace(/\[\[[^\]]*\]\]/g, 'null').replace(/\{\{[^}]*\}\}/g, 'null').replace(/\bNaN\b/g, 'null');
    try { b = JSON.parse(cleaned); } catch (e) { b = { ticker: '?', action: 'RAW', note: raw.slice(0, 300) }; }
  }
  if (b.src === 'cc-ac') {
    b.action = b.code == null ? 'SIGNAL (see chart)' : (ACT[String(Math.round(b.code))] || ('code ' + b.code));
    b.strategy = b.strat == null ? '' : (STR[String(Math.round(b.strat))] || '');
    delete b.code; delete b.strat; delete b.src;
  } else if (b.key !== undefined && b.key !== KEY) {
    b.note = 'KEY MISMATCH - check Webhook key in CC-Multi settings';
  }
  if (typeof b.rvol === 'number') b.rvol = Math.round(b.rvol * 10) / 10;
  delete b.key;
  b.received = new Date().toISOString();
  b.day = today;
  store.signals.unshift(b);
  store.log.push({ received: b.received, date: today, time: b.time ?? '', ticker: b.ticker ?? '', action: b.action ?? '', strategy: b.strategy ?? '', price: b.price ?? '', stop: b.stop ?? '', t1: b.t1 ?? '', t2: b.t2 ?? '', rvol: b.rvol ?? '', note: b.note ?? '' });
}
store.signals = store.signals.slice(0, 500);
store.log = store.log.slice(-20000);
return [{ json: { ok: true, stored: store.signals.length, logged: store.log.length } }];

const PAGE_JS = "
var MEM={};
var LS={get:function(k){if(MEM[k])return '1';try{return localStorage.getItem(k)}catch(e){return null}},set:function(k,v){MEM[k]=v;try{localStorage.setItem(k,v)}catch(e){}}};
var ctx=null, soundOn=false, nodes=[], alarmT=null, alarmEnd=null;
function honk(){ if(!ctx) return; var t=ctx.currentTime;
  for(var i=0;i<3;i++){ var s=t+i*0.55;
    [370,466].forEach(function(f){ var o=ctx.createOscillator(), g=ctx.createGain(), lp=ctx.createBiquadFilter();
      o.type='sawtooth'; o.frequency.value=f; lp.type='lowpass'; lp.frequency.value=1800;
      g.gain.setValueAtTime(0.0001,s); g.gain.exponentialRampToValueAtTime(0.35,s+0.03); g.gain.setValueAtTime(0.35,s+0.38); g.gain.exponentialRampToValueAtTime(0.0001,s+0.45);
      o.connect(lp); lp.connect(g); g.connect(ctx.destination); o.start(s); o.stop(s+0.5); nodes.push(o);
      o.onended=function(){ var k=nodes.indexOf(o); if(k>=0) nodes.splice(k,1); }; }); } }
function stopHonk(){ if(alarmT){ clearInterval(alarmT); alarmT=null; } if(alarmEnd){ clearTimeout(alarmEnd); alarmEnd=null; }
  nodes.slice().forEach(function(o){ try{o.stop()}catch(e){} }); nodes=[];
  document.getElementById('stopbar').style.display='none'; document.getElementById('stopbtn').className=''; }
function alarm(label){ if(!soundOn) return;
  var bar=document.getElementById('stopbar'); document.getElementById('stopwhat').textContent=label; bar.style.display='flex'; document.getElementById('stopbtn').className='on';
  if(!alarmT){ honk(); alarmT=setInterval(honk,3000); }
  if(alarmEnd) clearTimeout(alarmEnd); alarmEnd=setTimeout(stopHonk,60000); }
function enableSound(){ try{ ctx=ctx||new (window.AudioContext||window.webkitAudioContext)(); ctx.resume(); soundOn=true;
  var b=document.getElementById('snd'); b.textContent='🔊 Sound ON (test honk played)'; b.style.background='#16a34a'; honk(); }catch(e){} }
document.addEventListener('keydown',function(e){ if(e.key==='Escape'||e.key===' '){ if(alarmT){ e.preventDefault(); stopHonk(); } } });
function etNow(){ var p=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  var o={}; p.forEach(function(x){o[x.type]=x.value}); return {wd:o.weekday, m:(+o.hour%24)*60+(+o.minute), day:o.year+'-'+o.month+'-'+o.day}; }
function fire(key,label){ if(LS.get('cc_honk_'+key)) return; LS.set('cc_honk_'+key,'1'); alarm(label); }
function check(){
  var n=etNow(), wk=['Sat','Sun'].indexOf(n.wd)<0, ban=document.getElementById('banner');
  var inL = wk && n.m>=750 && n.m<840, after = wk && n.m>=840 && n.m<850;
  if(inL){ ban.style.display='block'; ban.style.background='#7c3aed'; ban.innerHTML='🍔 LUNCH BREAK — STOP: NO NEW TRADES until 2:00 PM ET<br><small>Open trades are still managed — follow SELL alerts</small>'; fire(n.day+'_start','LUNCH BREAK'); }
  else if(after){ ban.style.display='block'; ban.style.background='#0891b2'; ban.innerHTML='✅ LUNCH OVER — TRADING RESUMES<br><small>New entries allowed again</small>'; fire(n.day+'_end','LUNCH OVER'); }
  else { ban.style.display='none'; }
  var app=document.getElementById('app'), last=app.getAttribute('data-lunch');
  if(last){ last.split('~').forEach(function(id){ if(!id) return; var lab=id.indexOf('|end')>0?'LUNCH OVER':id.indexOf('|start')>0?'LUNCH BREAK':id.split('|').slice(1).join(' '); fire('alert_'+id,lab); }); }
}
function refresh(){ fetch(location.href,{cache:'no-store'}).then(function(r){return r.text()}).then(function(t){
  var d=new DOMParser().parseFromString(t,'text/html'), na=d.getElementById('app'); if(na){ var a=document.getElementById('app'); a.innerHTML=na.innerHTML; a.setAttribute('data-lunch',na.getAttribute('data-lunch')||''); } check(); }).catch(function(){}); }
(function(){ var app=document.getElementById('app'), l=app.getAttribute('data-lunch'); if(l) l.split('~').forEach(function(id){ if(id) LS.set('cc_honk_alert_'+id,'1'); });
  var n=etNow(); if(n.m>=750&&n.m<840) LS.set('cc_honk_'+n.day+'_start','1'); if(n.m>=840&&n.m<850) LS.set('cc_honk_'+n.day+'_end','1');
  check(); setInterval(check,5000); setInterval(refresh,10000); })();
";
// ?csv=1 -> full alert log as CSV (the Google Sheet reads this with IMPORTDATA)
const _q = ($input.first().json.query) || {};
if (_q.csv) {
  const L = ($getWorkflowStaticData('global').log || []);
  const cols = ['received','date','time','ticker','action','strategy','price','stop','t1','t2','rvol','note'];
  const q = v => '"' + String(v ?? '').replace(/"/g, '""') + '"';
  return [{ json: { html: cols.join(',') + '
' + L.map(r => cols.map(k => q(r[k])).join(',')).join('
') } }];
}
const _today = new Date().toLocaleString('en-CA', { timeZone: 'America/New_York' }).slice(0, 10);
const s = ($getWorkflowStaticData('global').signals || []).filter(x => !x.day || x.day === _today);
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const col = a => /DONE FOR TODAY/.test(a) ? '#991b1b' : /PROTECT PROFIT/.test(a) ? '#0d9488' : /LUNCH BREAK/.test(a) ? '#7c3aed' : /LUNCH OVER/.test(a) ? '#0891b2' : /BUY CALLS/.test(a) ? '#16a34a' : /BUY PUTS/.test(a) ? '#dc2626' : /HALF/.test(a) ? '#f59e0b' : /POSSIBLE/.test(a) ? '#a16207' : '#6b7280';
// events that honk: lunch start/end (once for all tickers), done-for-today and protect-profit (once per ticker)
const HONK = /LUNCH|DONE FOR TODAY|PROTECT PROFIT/;
const evIds = s.slice(0, 60).filter(x => HONK.test(String(x.action || ''))).map(x => /LUNCH/.test(x.action) ? String(x.time || '') + '|' + (/OVER/.test(x.action) ? 'end' : 'start') : String(x.time || '') + '|' + x.ticker + '|' + x.action);
const lunchId = esc(evIds.join('~'));
const rows = s.map(x => `<tr><td>${esc(x.time)}</td><td><b>${esc(x.ticker)}</b></td><td style="color:#fff;background:${col(x.action)};font-weight:${HONK.test(x.action) ? 'bold' : 'normal'}">${esc(x.action)}</td><td>${esc(x.strategy)}</td><td>${esc(x.price)}</td><td>${esc(x.stop)}</td><td>${esc(x.t1)}</td><td>${esc(x.t2)}</td><td>${x.rvol == null ? '' : esc(x.rvol) + 'x'}</td><td style="color:#9ca3af">${esc(x.note)}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CC Signals</title><style>body{font-family:system-ui;background:#0b0f14;color:#e5e7eb;margin:16px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:6px 8px;border-bottom:1px solid #1f2937;text-align:left}th{color:#9ca3af}#banner{display:none;color:#fff;font-size:26px;font-weight:800;text-align:center;padding:18px;border-radius:10px;margin:12px 0}#banner small{font-size:15px;font-weight:500}.btns{display:flex;gap:10px;flex-wrap:wrap}#stopbtn{background:#374151;color:#9ca3af;border:0;border-radius:8px;padding:10px 14px;font-size:15px;font-weight:700;cursor:pointer}#stopbtn.on{background:#dc2626;color:#fff;animation:blink 0.8s infinite}@keyframes blink{50%{opacity:.55}}#snd{background:#dc2626;color:#fff;border:0;border-radius:8px;padding:10px 14px;font-size:15px;cursor:pointer}.wrap{overflow-x:auto}#stopbar{display:none;position:fixed;left:16px;right:16px;bottom:16px;z-index:9;flex-direction:column;align-items:center;justify-content:center;background:#dc2626;color:#fff;border-radius:14px;padding:22px;font-size:30px;font-weight:900;cursor:pointer;box-shadow:0 6px 24px rgba(0,0,0,.6)}#stopbar small{font-size:15px;font-weight:600;margin-top:4px}</style></head><body><h2>Chart Commander signals <span style="font-size:13px;color:#9ca3af;font-weight:400">dashboard v6</span></h2><div class="btns"><button id="snd" onclick="enableSound()">🔇 Click once to turn ON the honk sound</button><button id="stopbtn" onclick="stopHonk()">🔕 STOP HONK</button></div><div id="banner"></div><div id="stopbar" onclick="stopHonk()"><span>🔕 STOP HONK</span><small id="stopwhat"></small></div><p style="color:#9ca3af">Updates every 10s (keep this page open). Newest first. Times ET.</p><div id="app" data-lunch="${lunchId}"><div class="wrap"><table><tr><th>Time</th><th>Ticker</th><th>Action</th><th>Strategy</th><th>Price</th><th>Stop</th><th>T1</th><th>T2</th><th>Vol</th><th>Note</th></tr>${rows || '<tr><td colspan=10>No signals yet</td></tr>'}</table></div></div><script>` + PAGE_JS + `</script></body></html>`;
return [{ json: { html } }];
